<template>
  <section v-if="item" class="grid gap-8 lg:grid-cols-[1fr_360px]"><div class="pc-card"><p class="text-xs uppercase tracking-wider text-indigo-400">Verified supplier listing</p><h1 class="mt-3 text-3xl font-bold text-white">{{ item.title }}</h1><p class="mt-5 text-sm text-slate-400">Listing ID {{ item.id }}</p><pre class="mt-6 overflow-auto rounded-lg bg-black/20 p-4 text-xs text-slate-300">{{ item.attributes_json || {} }}</pre></div><aside class="pc-card h-fit"><p class="text-sm text-slate-500">Supplier price</p><p class="mt-2 text-3xl font-bold text-white">{{ money(item.price_minor, item.currency) }}</p><p class="mt-2 text-sm text-emerald-300">{{ item.status }}</p><NuxtLink to="/market/post-request" class="btn-primary mt-6 block text-center">Request this solution</NuxtLink><button v-if="token" class="btn-secondary mt-3 w-full" @click="watch">Add to ideal list</button><p v-if="message" class="mt-3 text-xs text-emerald-300">{{ message }}</p></aside></section>
  <p v-else-if="error" class="pc-card text-sm text-red-300">{{ error }}</p>
</template>
<script setup lang="ts">
definePageMeta({ layout: 'default' }); const route = useRoute(); const { token } = useAuth(); const { getPublicListing, addWatchlist } = useCommerce(); const item = ref<any>(); const error = ref(''); const message = ref(''); const money = (value?: number, currency = 'EUR') => value == null ? 'Request price' : new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); async function watch() { await addWatchlist({ supplier_listing_id: item.value.id, target_price_minor: item.value.price_minor, currency: item.value.currency }); message.value = 'Added to ideal list.' }
onMounted(async () => { try { item.value = await getPublicListing(String(route.params.id)) } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
